  ('a1000000-0000-4000-8000-000000000001', 'Kaelith Vroun', '{"id":"a1000000-0000-4000-8000-000000000001","schemaVersion":2,"createdAt":"2026-01-01T00:00:00.000Z","updatedAt":"2026-01-01T00:00:00.000Z","identity":{"name":"Kaelith Vroun","player":"","className":"Wizard","subclass":"Evoker","level":3,"species":"Elf","background":"Sage","alignment":"Neutral","xp":0,"portrait":"assets/portraits/wizard.svg","accent":"#3f7bd6","tagline":"The library burns and he keeps reading"},"abilities":{"str":8,"dex":14,"con":13,"int":17,"wis":12,"cha":10},"saves":{"str":0,"dex":0,"con":0,"int":1,"wis":1,"cha":0},"skills":{"acrobatics":0,"animalHandling":0,"arcana":1,"athletics":0,"deception":0,"history":1,"insight":0,"intimidation":0,"investigation":1,"medicine":0,"nature":0,"perception":0,"performance":0,"persuasion":0,"religion":0,"sleightOfHand":0,"stealth":0,"survival":0},"combat":{"armorClass":12,"speed":30,"initiativeBonus":0,"hpMax":20,"hpCurrent":14,"hpTemp":0,"hitDieSize":6,"hitDiceTotal":3,"hitDiceSpent":0,"deathSuccesses":0,"deathFailures":0,"heroicInspiration":false,"exhaustion":0,"conditions":[],"attacks":[{"name":"Dagger","ability":"dex","proficient":true,"damage":"1d4","damageType":"Piercing","range":"Melee or 20/60 ft.","mastery":"Nick","notes":"","id":"kaelith-atk-1"},{"name":"Quarterstaff","ability":"str","proficient":true,"damage":"1d6","damageType":"Bludgeoning","range":"Melee","mastery":"Topple","notes":"Two-handed: 1d8.","id":"kaelith-atk-2"},{"name":"Ray of Frost","ability":"int","proficient":true,"damage":"1d8","damageType":"Cold","range":"60 feet","mastery":"—","notes":"Cantrip. The target''s Speed drops by 10 feet.","id":"kaelith-atk-3"}]},"spellcasting":{"ability":"int","slots":[{"level":1,"total":4,"used":2},{"level":2,"total":2,"used":0}],"spells":[{"name":"Ray of Frost","level":0,"school":"Evocation","castingTime":"1 action","range":"60 feet","components":"V, S","duration":"Instantaneous","concentration":false,"ritual":false,"prepared":true,"description"