sleep.","usesMax":0,"usesSpent":0,"recharge":"none","id":"kaelith-feat-4"}],"languages":["Common","Elvish","Draconic","Deep Speech"],"armor":"None","weapons":"Simple weapons","tools":"Calligrapher''s Supplies"},"journal":{"personality":"Speaks slowly and quotes books nobody else has read.","ideals":"Knowledge that is not shared rots.","bonds":"The library of Vroun burned because of him. He is rebuilding it from memory.","flaws":"Puts an interesting fact ahead of his own safety.","backstory":"Third son of a minor house, he traded the title for an archivist post. In the cellars he found a treatise on evocation that should not exist.","allies":"Master Oriel, of the Crystal College. Fenn the bookseller, who owes him favours.","notes":"Chasing the scattered pages of the Aldaric treatise."}}'::jsonb),
  ('a1000000-0000-4000-8000-000000000002', 'Brann Oldiron', '{"id":"a1000000-0000-4000-8000-000000000002","schemaVersion":2,"createdAt":"2026-01-01T00:00:00.000Z","updatedAt":"2026-01-01T00:00:00.000Z","identity":{"name":"Brann Oldiron","player":"","className":"Barbarian","subclass":"Path of the Berserker","level":3,"species":"Goliath","background":"Soldier","alignment":"Neutral","xp":0,"portrait":"assets/portraits/barbarian.svg","accent":"#e03a2f","tagline":"Talks little. Breaks plenty."},"abilities":{"str":17,"dex":13,"con":16,"int":8,"wis":12,"cha":10},"saves":{"str":1,"dex":0,"con":1,"int":0,"wis":0,"cha":0},"skills":{"acrobatics":0,"animalHandling":0,"arcana":0,"athletics":1,"deception":0,"history":0,"insight":0,"intimidation":1,"investigation":0,"medicine":0,"nature":0,"perception":1,"performance":0,"persuasion":0,"religion":0,"sleightOfHand":0,"stealth":0,"survival":1},"combat":{"armorClass":15,"speed":40,"initiativeBonus":0,"hpMax":34,"hpCurrent":26,"hpTemp":0,"hitDieSize":12,"hitDiceTotal":3,"hitDiceSpent":0,"deathSuccesses":0,"deathFailures":0,"heroicInspiration":true,"exhaustion":0,"conditions":[],"attacks":[{"name":"Greataxe","ability":"str","proficient":true,"damage":"1d12","damageType":"Slashing","range":"Melee","mastery":"Cleave","notes":"Two-handed. +2 damage while Raging.","id":"brann-atk-1"},{"name":"Handaxe","ability":"str","proficient":true,"damage":"1d6","damageType":"Slashing","range":"Melee or 20/60 ft.","mastery":"Vex","notes":"","id":"brann-atk-2"},{"name":"Unarmed Strike","ability":"str","proficient":true,"damage":"1","damageType":"Bludgeoning","range":"Melee","mastery":"—","notes":"","id":"brann-atk-3"}]},"spellcasting":{"ability":null,"slots":[],"spells":[],"notes":""},"inventory":{"coins":{"pp":0,"gp":12,"ep":0,"sp":40,"cp":0},"items":[{"name":"Greataxe","quantity":1,"weight":7,"attuned":false,"equipped":true,"notes":"","id":"brann-item-1"},{"name":"Handaxe","quantity":2,"weight":2,"attuned":false,"equipped":false,"notes":"","id":"brann-item-2"},{"name":"Hide Armor","quantity":1,"weight":12,"attuned":false,"equipped":true,"notes":"","id":"brann-item-3"},{"name":"Explorer''s Pack","quantity":1,"weight":55,"attuned":false,"equipped":false,"notes":"","id":"brann-item-4"},{"name":"Hempen Rope (50 feet)","quantity":1,"weight":5,"attuned":false,"equipped":false,"notes":"","id":"brann-item-5"},{"name":"Rations","quantity":10,"weight":2,"attuned":false,"equipped":false,"notes":"","id":"brann-item-6"},{"name":"Regimental medal","quantity":1,"weight":0,"attuned":false,"equipped":false,"notes":"From the Second of Ravenstone. All dead but him.","id":"brann-item-7"}],"notes":""},"features":{"entries":[{"name":"Rage","source":"Barbarian","description":"Bonus Action. Advantage on Strength checks and saves, +2 melee damage, and Resistance to Bludgeoning, Piercing and Slashing damage. Lasts 1 minute.","usesMax":3,"usesSpent":1,"recharge":"long","id":"brann-feat-1"},{"name":"Reckless Attack","source":"Barbarian","description":"When you attack with Strength you roll with Advantage; in exchange, attacks against you have Advantage until your next turn.","usesMax":0,"usesSpent":0,"recharge":"none","id":"brann-feat-2"},{"name":"Danger Sense","source":"Barbarian","description":"Advantage on Dexterity saves against effects you can see (traps, spells).","usesMax":0,"usesSpent":0,"recharge":"none","id":"brann-feat-3"},{"name":"Frenzy","source":"Path of the Berserker","description":"While Raging you can make one extra melee attack as a Bonus Action on each of your turns.","usesMax":0,"usesSpent":0,"recharge":"none","id":"brann-feat-4"},{"name":"Stone''s Endurance","source":"Goliath","description":"As a Reaction you reduce damage taken by 1d12 plus your Constitution modifier. Long Rest.","usesMax":1,"usesSpent":0,"recharge":"long","id":"brann-feat-5"}],"languages":["Common","Giant"],"armor":"Light and Medium armor, Shields","weapons":"Simple and Martial weapons","tools":"A set of bone dice"},"journal":{"personality":"Counts the enemies before the fight. Out loud.","ideals":"A given word is a weight. You do not put it down.","bonds":"The Second of Ravenstone fell at the Kettur pass. He arrived too late.","flaws":"Does not know how to retreat. Never has.","backstory":"He came down from the mountains to work as an escort and ended up in a regiment. When it was wiped out he kept fighting alone until some adventurers picked him up half dead.","allies":"The cleric Sister Maren stitched his side up and never charged him.","notes":"Looking for the officer who ordered the advance at Kettur."}}'::jsonb),
  ('a1000000-0000-4000-8000-000000000003', 'Nyx', '{"id":"a1000000-0000-4000-8000-000000000003","schemaVersion":2,"createdAt":"2026-01-01T00:00:00.000Z","updatedAt":"2026-01-01T00:00:00.000Z","identity":{"name":"Nyx","player":"","className":"Rogue","subclass":"Thief","level":3,"species":"Tiefling","background":"Criminal","alignment":"Neutral","xp":0,"portrait":"assets/portraits/rogue.svg","accent":"#6f7cd1","tagline":"You never saw her come in"},"abilities":{"str":10,"dex":17,"con":13,"int":13,"wis":12,"cha":14},"saves":{"str":0,"dex":1,"con":0,"int":1,"wis":0,"cha":0},"skills":{"acrobatics":1,"animalHandling":0,"arcana":0,"athletics":0,"deception":1,"history":0,"insight":0,"intimidation":0,"investigation":1,"medicine":0,"nature":0,"perception":1,"performance":0,"persuasion":0,"religion":0,"sleightOfHand":1,"stealth":1,"survival":0},"combat":{"armorClass":14,"speed":30,"initiativeBonus":0,"hpMax":21,"hpCurrent":21,"hpTemp":0,"hitDieSize":8,"hitDiceTotal":3,"hitDiceSpent":0,"deathSuccesses":0,"deathFailures":0,"heroicInspiration":false,"exhaustion":0,"conditions":[],"attacks":[{"name":"Rapier","ability":"dex","proficient":true,"damage":"1d8","damageType":"Piercing","range":"Melee","mastery":"Vex","notes":"Finesse.","id":"nyx-atk-1"},{"name":"Thrown Dagger","ability":"dex","proficient":true,"damage":"1d4","damageType":"Piercing","range":"Melee or 20/60 ft.","mastery":"Nick","notes":"","id":"nyx-atk-2"},{"name":"Shortbow","ability":"dex","proficient":true,"damage":"1d6","damageType":"Piercing","range":"80/320 ft.","mastery":"Vex","notes":"","id":"nyx-atk-3"}]},"spellcasting":{"ability":null,"slots":[],"spells":[],"notes":"No spellcasting. The Thaumaturgy cantrip comes from her fiendish legacy (1/day)."},"inventory":{"coins":{"pp":3,"gp":60,"ep":0,"sp":0,"cp":0},"items":[{"name":"Rapier","quantity":1,"weight":2,"attuned":false,"equipped":true,"notes":"","id":"nyx-item-1"},{"name":"Dagger","quantity":4,"weight":1,"attuned":false,"equipped":false,"notes":"Two at the belt,